function inicializarDadosLighthouse(forcar) {
    forcar = forcar === true;

    let existente = [];
    try {
        existente = JSON.parse(localStorage.getItem("despesas")) || [];
    } catch (e) {
        existente = [];
    }

    const jaImportado = localStorage.getItem("lighthouse_seed_v1") === "1";

    if (forcar || (!jaImportado && existente.length === 0)) {
        localStorage.setItem("despesas", JSON.stringify(DADOS_INICIAIS_LIGHTHOUSE));
        localStorage.setItem("lighthouse_seed_v1", "1");
        console.log("Base inicial do Lighthouse carregada:", DADOS_INICIAIS_LIGHTHOUSE.length, "registros.");
        return true;
    }
    console.log("Base inicial NAO carregada (ja existiam", existente.length, "registros salvos).");
    return false;
}

function carregarBaseCsvManual() {
    const atual = JSON.parse(localStorage.getItem("despesas") || "[]");
    const confirmar = confirm(
        "Isso vai SUBSTITUIR os " + atual.length + " registro(s) atualmente salvos " +
        "pelos " + DADOS_INICIAIS_LIGHTHOUSE.length + " registros do CSV. Deseja continuar?"
    );
    if (!confirmar) return;
    inicializarDadosLighthouse(true);
    alert("Base do CSV carregada: " + DADOS_INICIAIS_LIGHTHOUSE.length + " registros.");
    window.location.reload();
}
